Here is the commit message:
bridge: cfm: Fix race condition in peer_mep deletion

When a peer MEP is being deleted, cancel_delayed_work_sync() is called
on ccm_rx_dwork before freeing. However, br_cfm_frame_rx() runs in
softirq context under rcu_read_lock (without RTNL) and can re-schedule
ccm_rx_dwork via ccm_rx_timer_start() between cancel_delayed_work_sync()
returning and kfree_rcu() being called.

The following is a simple race scenario:

           cpu0                                     cpu1

mep_delete_implementation()
  cancel_delayed_work_sync(ccm_rx_dwork);
                                           br_cfm_frame_rx()
                                             // peer_mep still in hlist
                                             if (peer_mep->ccm_defect)
                                               ccm_rx_timer_start()
                                                 queue_delayed_work(ccm_rx_dwork)
  hlist_del_rcu(&peer_mep->head);
  kfree_rcu(peer_mep, rcu);
                                           ccm_rx_work_expired()
                                             // on freed peer_mep

To prevent this, cancel_delayed_work_sync() is replaced with
disable_delayed_work_sync() in both peer MEP deletion paths, so
that subsequent queue_delayed_work() calls from br_cfm_frame_rx()
are silently rejected.

The cc_peer_disable() helper retains cancel_delayed_work_sync()
because it is also used for the CC enable/disable toggle path where
the work must remain re-schedulable.

Fixes: dc32cbb3dbd7 ("bridge: cfm: Kernel space implementation of CFM. CCM frame RX added.")
Signed-off-by: Hyunwoo Kim <imv4bel@gmail.com>
Reviewed-by: Ido Schimmel <idosch@nvidia.com>
Link: https://patch.msgid.link/abBgYT5K_FI9rD1a@v4bel
Signed-off-by: Jakub Kicinski <kuba@kernel.org>

Here is the root cause:
The race condition occurs because `cancel_delayed_work_sync()` only cancels any currently pending work but does not prevent subsequent `queue_delayed_work()` calls (from the softirq RX handler `br_cfm_frame_rx()`) after it returns. This allows the delayed work to be re-scheduled on a peer MEP entry that is about to be freed via `kfree_rcu()`, causing a use-after-free when the work eventually executes.

Here is the patch:

 static void mep_delete_implementation(struct net_bridge *br,
 				      struct br_cfm_mep *mep)
 {
 	struct br_cfm_peer_mep *peer_mep;
 	struct hlist_node *n_store;

 	ASSERT_RTNL();

 	/* Empty and free peer MEP list */
 	hlist_for_each_entry_safe(peer_mep, n_store, &mep->peer_mep_list, head) {
-		cancel_delayed_work_sync(&peer_mep->ccm_rx_dwork);
+		disable_delayed_work_sync(&peer_mep->ccm_rx_dwork);
 		hlist_del_rcu(&peer_mep->head);
 		kfree_rcu(peer_mep, rcu);
 	}

 	cancel_delayed_work_sync(&mep->ccm_tx_dwork);

 	RCU_INIT_POINTER(mep->b_port, NULL);
 	hlist_del_rcu(&mep->head);
 	kfree_rcu(mep, rcu);

 	if (hlist_empty(&br->mep_list))
 		br_del_frame(br, &cfm_frame_type);
 }


 int br_cfm_cc_peer_mep_remove(struct net_bridge *br, const u32 instance,
 			      u32 mepid,
 			      struct netlink_ext_ack *extack)
 {
 	struct br_cfm_peer_mep *peer_mep;
 	struct br_cfm_mep *mep;

 	ASSERT_RTNL();

 	mep = br_mep_find(br, instance);
 	if (!mep) {
 		NL_SET_ERR_MSG_MOD(extack,
 				   "MEP instance does not exists");
 		return -ENOENT;
 	}

 	peer_mep = br_peer_mep_find(mep, mepid);
 	if (!peer_mep) {
 		NL_SET_ERR_MSG_MOD(extack,
 				   "Peer MEP-ID does not exists");
 		return -ENOENT;
 	}

-	cc_peer_disable(peer_mep);
+	disable_delayed_work_sync(&peer_mep->ccm_rx_dwork);

 	hlist_del_rcu(&peer_mep->head);
 	kfree_rcu(peer_mep, rcu);

 	return 0;
 }



